  'media_consent_send_fast': {'de': 'Schnell senden', 'en': 'Send fast', 'es': 'Enviar rápido', 'hu': 'Gyors küldés', 'sv': 'Skicka snabbt', 'ar': 'إرسال سريع', 'he': 'שליחה מהירה', 'fa': 'ارسال سریع', 'fr': 'Envoyer rapidement', 'it': 'Invia rapidamente', 'pt': 'Enviar rápido', 'nl': 'Snel versturen', 'pl': 'Wyślij szybko', 'ro': 'Trimite rapid', 'cs': 'Odeslat rychle', 'sk': 'Odoslať rýchlo', 'hr': 'Pošalji brzo', 'sr': 'Пошаљи брзо', 'bg': 'Изпрати бързо', 'el': 'Γρήγορη αποστολή', 'da': 'Send hurtigt', 'fi': 'Lähetä nopeasti', 'no': 'Send raskt', 'uk': 'Надіслати швидко', 'ru': 'Отправить быстро', 'tr': 'Hızlı gönder', 'zh': '快速发送', 'ja': '高速に送信', 'ko': '빠르게 보내기', 'hi': 'तेज़ी से भेजें', 'th': 'ส่งอย่างรวดเร็ว', 'vi': 'Gửi nhanh', 'id': 'Kirim cepat', 'ms': 'Hantar pantas', },
